INSERT INTO fleet_workspaces (workspace_id, name, description, state, repository_count, actor_kind, actor_human_id, actor_service_id, actor_endpoint_id, actor_session_id, actor_router_component, request_id, fleet_position, router_time, time_basis, origin_installation, origin_machine, import_digest, created_at, updated_at) VALUES (?1, ?2, ?3, ?4, CAST(?5 AS INTEGER), ?6, ?7, ?8, ?9, ?10, ?11, ?12, CAST(?13 AS INTEGER), ?14, ?15, ?16, ?17, ?18, CAST(?19 AS INTEGER), CAST(?19 AS INTEGER)) ON CONFLICT(workspace_id) DO UPDATE SET name=excluded.name, description=excluded.description, state=excluded.state, repository_count=excluded.repository_count, actor_kind=excluded.actor_kind, actor_human_id=excluded.actor_human_id, actor_service_id=excluded.actor_service_id, actor_endpoint_id=excluded.actor_endpoint_id, actor_session_id=excluded.actor_session_id, actor_router_component=excluded.actor_router_component, request_id=excluded.request_id, fleet_position=excluded.fleet_position, router_time=excluded.router_time, time_basis=excluded.time_basis, origin_installation=excluded.origin_installation, origin_machine=excluded.origin_machine, import_digest=coalesce(fleet_workspaces.import_digest,excluded.import_digest), updated_at=excluded.updated_at;
